import { identityBaseUrl } from './env';
import { ApiError, networkError, toApiError } from './errors';
import type { operations } from './identity.generated';

/**
 * WAWU ID (the sign-in service) is a separate server from the Hub. Its calls
 * are typed from WAWU ID's published contract (`contract/identity/openapi.json`,
 * regenerated by `npm run api -- --identity ../wawu-id` into
 * `identity.generated.ts`; AUTH-05, BACKEND_GAPS G-5), and written here, in the
 * data layer, and nowhere else. Each still refuses an answer that lacks the
 * fields it uses, because a server that drifted from its contract must not
 * sign anyone in with half a session.
 */

/** The request body and the success body of one WAWU ID operation. */
type Request<O extends keyof operations> = operations[O] extends {
  requestBody: { content: { 'application/json': infer B } };
}
  ? B
  : never;
type Answer<O extends keyof operations> = operations[O] extends {
  responses: { 200: { content: { 'application/json': infer A } } };
}
  ? A
  : never;

export type TokenPair = Answer<'refresh'>['data'];

async function post<O extends keyof operations>(path: string, body: Request<O>): Promise<Partial<Answer<O>> | null> {
  let response: Response;
  try {
    response = await fetch(`${identityBaseUrl}${path}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json' },
      body: JSON.stringify(body),
    });
  } catch {
    throw networkError();
  }
  const payload: unknown = await response.json().catch(() => null);
  if (!response.ok) throw toApiError(response.status, payload);
  return payload as Partial<Answer<O>> | null;
}

function readTokenPair(payload: { data?: Partial<TokenPair> } | null): TokenPair {
  const accessToken = payload?.data?.accessToken;
  const refreshToken = payload?.data?.refreshToken;
  if (typeof accessToken !== 'string' || typeof refreshToken !== 'string') {
    throw new ApiError('unknown', 0, 'Sign-in gave an unexpected answer. Try again.');
  }
  return { accessToken, refreshToken };
}

/** Email or phone, plus password. Rejects with an ApiError (unauthorized, EMAIL_NOT_VERIFIED, ...). */
export async function loginRequest(identifier: string, password: string): Promise<TokenPair> {
  return readTokenPair(await post<'login'>('/auth/login', { identifier, password }));
}

/** Trades the refresh token for a new pair. WAWU ID rotates it, so the old one stops working. */
export async function refreshRequest(refreshToken: string): Promise<TokenPair> {
  return readTokenPair(await post<'refresh'>('/auth/refresh', { refreshToken }));
}

/** What the reset-link request answers: how long the emailed link lasts, or null when the server does not say. */
export type ResetLinkAnswer = { expiresInSeconds: number | null };

/**
 * Asks WAWU ID to email a reset link (`method: 'email'`; without it the server
 * sends a WhatsApp code instead). It answers the same whether or not an account
 * exists. The link opens WAWU ID's own web reset page: the app has no New
 * password screen. `expiresInSeconds` is the link's real lifetime; a server that
 * does not send it (BACKEND_GAPS.md G-26) gives null and the screen leaves the
 * figure out.
 */
export async function forgotPasswordRequest(identifier: string): Promise<ResetLinkAnswer> {
  const payload = await post<'forgotPassword'>('/auth/forgot-password', { identifier, method: 'email' });
  const seconds: unknown = payload?.data?.expiresInSeconds;
  return { expiresInSeconds: typeof seconds === 'number' && Number.isFinite(seconds) && seconds > 0 ? seconds : null };
}
